import AppKit
import CryptoKit
import ImageIO
import UniformTypeIdentifiers

enum ClipboardHistoryCaptureService {
    static let markerType = NSPasteboard.PasteboardType(
        "com.omzcj.minitools.clipboard-history-item"
    )

    private static let ignoredTypes: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType"
    ]

    struct Snapshot: Sendable {
        let payloads: [ClipboardHistoryCapturedRepresentation]
        let plainText: String?
        let imageData: Data?
        let fileNames: [String]
        let hasRichText: Bool
        let sourceBundleIdentifier: String?
        let sourceName: String?
        let copiedAt: Date
    }

    static func capture(from pasteboard: NSPasteboard, sourceApplication: NSRunningApplication?,
                        now: Date = Date()) -> ClipboardHistoryCapture? {
        snapshot(from: pasteboard, sourceApplication: sourceApplication, now: now).flatMap(process)
    }

    /// Read AppKit/pasteboard values on the caller's main actor; only Sendable data leaves it.
    static func snapshot(
        from pasteboard: NSPasteboard,
        sourceApplication: NSRunningApplication?,
        now: Date = Date()
    ) -> Snapshot? {
        guard let pasteboardItems = pasteboard.pasteboardItems, !pasteboardItems.isEmpty else {
            return nil
        }
        let advertisedTypes = Set(pasteboardItems.flatMap(\.types).map(\.rawValue))
        guard !advertisedTypes.contains(markerType.rawValue),
              ignoredTypes.isDisjoint(with: advertisedTypes) else {
            return nil
        }

        var payloads: [ClipboardHistoryCapturedRepresentation] = []
        // Prefer an advertised plain representation before importing any HTML/RTF.
        // HTML import uses AppKit and stays on the main caller when no plain alternative exists.
        var plainText = pasteboardItems.lazy.compactMap { $0.string(forType: .string) }.first
        var imageData: Data?
        var fileNames: [String] = []
        var hasRichText = false

        for (itemIndex, item) in pasteboardItems.enumerated() {
            for type in item.types where isAllowed(type) {
                guard let data = item.data(forType: type), !data.isEmpty else { continue }
                payloads.append(
                    ClipboardHistoryCapturedRepresentation(
                        itemIndex: itemIndex,
                        typeIdentifier: type.rawValue,
                        data: data
                    )
                )
                if type == .string, plainText == nil {
                    plainText = item.string(forType: .string)
                }
                if type == .rtf || type == .html {
                    hasRichText = true
                    if plainText == nil {
                        plainText = attributedPlainText(data: data, type: type)
                    }
                }
                if UTType(type.rawValue)?.conforms(to: .image) == true, imageData == nil {
                    imageData = data
                }
                if type == .fileURL,
                   let value = item.string(forType: .fileURL),
                   let url = URL(string: value) {
                    fileNames.append(url.lastPathComponent)
                }
            }
        }

        guard !payloads.isEmpty else { return nil }
        return Snapshot(payloads: payloads, plainText: plainText, imageData: imageData,
            fileNames: fileNames, hasRichText: hasRichText,
            sourceBundleIdentifier: sourceApplication?.bundleIdentifier,
            sourceName: sourceApplication?.localizedName, copiedAt: now)
    }

    /// Hashing and ImageIO thumbnail encoding do not use AppKit and run off the main actor.
    static func process(_ snapshot: Snapshot) -> ClipboardHistoryCapture? {
        let payloads = snapshot.payloads
        let plainText = snapshot.plainText
        let fileNames = snapshot.fileNames
        let kind = classify(
            plainText: plainText,
            hasRichText: snapshot.hasRichText,
            hasImage: snapshot.imageData != nil,
            fileNames: fileNames
        )
        let image = snapshot.imageData.flatMap(imagePreview)
        let dimensions = image?.dimensions
        let summary = summary(
            kind: kind,
            plainText: plainText,
            fileNames: fileNames,
            dimensions: dimensions
        )
        let contentHash = hash(payloads)
        let id = UUID()
        let representations = payloads.enumerated().map { offset, payload in
            ClipboardHistoryRepresentation(
                itemIndex: payload.itemIndex,
                typeIdentifier: payload.typeIdentifier,
                fileName: "payload-\(offset).bin"
            )
        }
        let thumbnailData = image?.thumbnail
        let sourceName = snapshot.sourceName
        let item = ClipboardHistoryItem(
            id: id,
            copiedAt: snapshot.copiedAt,
            sourceBundleIdentifier: snapshot.sourceBundleIdentifier,
            sourceApplicationName: sourceName,
            kind: kind,
            summary: summary,
            searchableText: ([plainText, fileNames.joined(separator: " "), sourceName]
                .compactMap { $0 }
                .joined(separator: "\n")),
            plainText: plainText,
            contentHash: contentHash,
            pixelWidth: dimensions?.width,
            pixelHeight: dimensions?.height,
            thumbnailFileName: thumbnailData == nil ? nil : "thumbnail.png",
            representations: representations
        )
        return ClipboardHistoryCapture(item: item, payloads: payloads, thumbnailData: thumbnailData)
    }

    static func itemForWriting(
        _ item: ClipboardHistoryItem,
        payloads: [ClipboardHistoryCapturedRepresentation],
        plainTextOnly: Bool
    ) -> [NSPasteboardItem]? {
        if plainTextOnly {
            guard let plainText = item.plainText, !plainText.isEmpty else { return nil }
            let pasteboardItem = NSPasteboardItem()
            pasteboardItem.setString(plainText, forType: .string)
            pasteboardItem.setString(item.id.uuidString, forType: markerType)
            return [pasteboardItem]
        }

        let grouped = Dictionary(grouping: payloads, by: \.itemIndex)
        let output = grouped.keys.sorted().compactMap { index -> NSPasteboardItem? in
            guard let values = grouped[index] else { return nil }
            let pasteboardItem = NSPasteboardItem()
            for value in values {
                pasteboardItem.setData(
                    value.data,
                    forType: NSPasteboard.PasteboardType(value.typeIdentifier)
                )
            }
            if index == grouped.keys.min() {
                pasteboardItem.setString(item.id.uuidString, forType: markerType)
            }
            return pasteboardItem.types.isEmpty ? nil : pasteboardItem
        }
        return output.isEmpty ? nil : output
    }

    private static func isAllowed(_ type: NSPasteboard.PasteboardType) -> Bool {
        if type == .string || type == .rtf || type == .html || type == .fileURL {
            return true
        }
        guard let uniformType = UTType(type.rawValue) else { return false }
        return uniformType.conforms(to: .image)
    }

    private static func classify(
        plainText: String?,
        hasRichText: Bool,
        hasImage: Bool,
        fileNames: [String]
    ) -> ClipboardHistoryKind {
        if !fileNames.isEmpty { return .files }
        if hasImage { return .image }
        if let plainText {
            let value = plainText.trimmingCharacters(in: .whitespacesAndNewlines)
            if URL(string: value).flatMap(\.scheme) != nil { return .link }
            if isColor(value) { return .color }
        }
        return hasRichText ? .richText : .text
    }

    private static func isColor(_ value: String) -> Bool {
        let raw = value.hasPrefix("#") ? String(value.dropFirst()) : value
        guard raw.count == 6, raw.allSatisfy({ $0.isHexDigit }) else { return false }
        return value.hasPrefix("#") || raw.contains(where: { "abcdefABCDEF".contains($0) })
    }

    private static func summary(
        kind: ClipboardHistoryKind,
        plainText: String?,
        fileNames: [String],
        dimensions: (width: Int, height: Int)?
    ) -> String {
        if kind == .files {
            if fileNames.count == 1 { return fileNames[0] }
            return "\(fileNames.count) 个文件"
        }
        if let dimensions {
            return "\(dimensions.width) × \(dimensions.height)"
        }
        let normalized = plainText?
            .replacingOccurrences(of: "\r\n", with: "\n")
            .replacingOccurrences(of: "\r", with: "\n")
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        if normalized.count <= 180 { return normalized }
        return String(normalized.prefix(176)) + "…"
    }

    private static func attributedPlainText(
        data: Data,
        type: NSPasteboard.PasteboardType
    ) -> String? {
        let documentType: NSAttributedString.DocumentType = type == .rtf ? .rtf : .html
        return try? NSAttributedString(
            data: data,
            options: [.documentType: documentType],
            documentAttributes: nil
        ).string
    }

    private static func imagePreview(_ data: Data) -> (dimensions: (width: Int, height: Int)?, thumbnail: Data?)? {
        guard let source = CGImageSourceCreateWithData(data as CFData,
            [kCGImageSourceShouldCache: false] as CFDictionary) else { return nil }
        let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [String: Any]
        let width = properties?[kCGImagePropertyPixelWidth as String] as? Int
        let height = properties?[kCGImagePropertyPixelHeight as String] as? Int
        let dimensions = width.flatMap { width in height.map { (width: width, height: $0) } }
        guard let image = CGImageSourceCreateThumbnailAtIndex(source, 0, [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceThumbnailMaxPixelSize: 480,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceShouldCacheImmediately: true
        ] as CFDictionary) else { return (dimensions, nil) }
        let output = NSMutableData()
        guard let destination = CGImageDestinationCreateWithData(output,
            UTType.png.identifier as CFString, 1, nil) else { return (dimensions, nil) }
        CGImageDestinationAddImage(destination, image, nil)
        return (dimensions, CGImageDestinationFinalize(destination) ? output as Data : nil)
    }

    private static func hash(_ payloads: [ClipboardHistoryCapturedRepresentation]) -> String {
        var hasher = SHA256()
        for payload in payloads.sorted(by: {
            ($0.itemIndex, $0.typeIdentifier) < ($1.itemIndex, $1.typeIdentifier)
        }) {
            hasher.update(data: Data("\(payload.itemIndex):\(payload.typeIdentifier):".utf8))
            hasher.update(data: payload.data)
        }
        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }
}
